<template>
  <main class="invoice-match-page" v-loading="loading">
    <header class="match-heading"><div><h1>发票匹配</h1><span>将发票与采购、付款等业务单据进行匹配，匹配后才进行现金分配。</span></div><div class="heading-actions"><el-button @click="$router.push('/finance/invoices')">返回发票列表</el-button><el-button :loading="saving" :disabled="isFullyMatched" @click="saveMatches">保存匹配</el-button><el-button type="success" class="green-button" :loading="saving" @click="confirmMatches">确认匹配</el-button></div></header>
    <el-alert class="business-alert" :closable="false" type="info" show-icon title="发票匹配以价税合计为口径；税额随采购结算来源一并匹配，不可单独追加。"/>
    <section class="invoice-summary"><h2>发票信息</h2><div><span>发票记录号<b>{{invoice.document_no||'—'}}</b></span><span>发票号码/代码<b>{{invoice.invoice_no||'—'}}<i v-if="invoice.invoice_code">/{{invoice.invoice_code}}</i></b></span><span>供应商<b>{{invoice.party_name_snapshot||'—'}}</b></span><span>开票日期<b>{{invoice.invoice_date||'—'}}</b></span><span>发票价税合计（CNY）<strong>{{money(invoice.amount_incl_tax)}}</strong></span><span>已匹配金额（CNY）<strong class="green">{{money(currentMatched)}}</strong></span><span>未匹配金额（CNY）<strong class="red">{{money(unmatchedAmount)}}</strong></span></div></section>
    <section class="source-card"><el-form class="source-filters" label-position="top"><el-form-item label="匹配来源"><el-select v-model="sourceType"><el-option label="采购结算单" value="purchase_settlement_source"/></el-select></el-form-item><el-form-item label="供应商"><el-input :value="invoice.party_name_snapshot" disabled/></el-form-item><el-form-item label="业务日期"><el-date-picker v-model="businessDateRange" type="daterange" value-format="yyyy-MM-dd" range-separator="~" start-placeholder="开始日期" end-placeholder="结束日期"/></el-form-item><el-form-item label="结算单号"><el-input v-model.trim="filters.settlement_source_no" placeholder="请输入结算单号"/></el-form-item><el-form-item label="采购订单号"><el-input v-model.trim="filters.purchase_order_no" placeholder="请输入采购订单号"/></el-form-item><div class="filter-actions"><el-button @click="reset">重置</el-button><el-button type="success" class="green-button" @click="search">查询</el-button></div></el-form>
      <h2>可匹配结算来源（已选择 {{ selectedCount }} 条）</h2>
      <el-table :data="rows" row-key="id" border size="small" class="source-table"><el-table-column width="50"><template slot="header"><el-checkbox :value="allPageSourcesSelected" :disabled="!matchableRows.length||isFullyMatched" @change="togglePageSelection"/></template><template slot-scope="{row}"><el-checkbox :value="Boolean(selected[row.id])" :disabled="isFullyMatched||Number(row.available_amount)<=0" @change="checked=>toggleSelection(row,checked)"/></template></el-table-column><el-table-column prop="settlement_source_no" label="结算来源单号" min-width="140"/><el-table-column prop="purchase_order_no" label="采购订单号" min-width="130"/><el-table-column prop="receipt_no" label="收货单号" min-width="130"/><el-table-column prop="business_date" label="业务日期" min-width="100"/><amount-column label="当前应付（价税合计 CNY）" prop="current_payable_amount"/><amount-column label="已开票金额（CNY）" prop="invoiced_amount"/><amount-column label="可用金额（CNY）" prop="available_amount"/><el-table-column label="本次匹配金额（CNY）" min-width="150"><template slot-scope="{row}"><el-input v-if="selected[row.id]" v-model.trim="selected[row.id].allocated_amount" size="small" @input="validateRow(row)"/><span v-else>0.00</span></template></el-table-column></el-table>
      <div class="source-total"><b>合计</b><span>{{money(summary.payable_amount)}}</span><span>{{money(summary.invoiced_amount)}}</span><span>{{money(summary.available_amount)}}</span><strong>{{money(selectedTotal)}}</strong></div>
      <el-pagination background layout="total, prev, pager, next, sizes, jumper" :current-page="page" :page-size="perPage" :page-sizes="[10,20,50]" :total="total" @current-change="p=>{page=p;load()}" @size-change="s=>{perPage=s;page=1;load()}"/>
    </section>
    <section class="match-history"><h2>匹配历史</h2><el-table :data="invoice.allocations||[]" border size="small" empty-text="暂无匹配记录"><el-table-column prop="source_document_no" label="结算来源单号" min-width="180"/><el-table-column prop="source_business_type" label="来源类型" min-width="160"/><el-table-column label="本次匹配金额（CNY）" min-width="160" align="right"><template slot-scope="{row}">{{money(row.allocated_amount)}}</template></el-table-column><el-table-column prop="status" label="状态" min-width="110"/></el-table></section>
    <section class="match-foot"><div class="match-check"><i :class="matchComplete?'el-icon-success pass':'el-icon-warning-outline wait'"/><div><b>匹配校验　{{matchComplete?'通过':'待完成'}}</b><small>发票价税合计 = 本次完整匹配集合金额</small></div></div><div><span>已保存匹配金额（CNY）</span><b class="green">{{money(currentMatched)}}</b></div><div><span>本次完整匹配集合金额（CNY）</span><b class="green">{{money(selectedTotal)}}</b></div><div><span>保存后剩余未匹配金额（CNY）</span><b>{{money(remainingAfterSelection)}}</b></div></section>
  </main>
</template>

<script>
import { getFinanceInvoice, listInvoiceMatchingSources, saveFinanceInvoiceMatches, confirmFinanceInvoice } from '../../../api/erp/finance'
export default {components:{AmountColumn:{props:['label','prop'],methods:{f(v){return Number(v||0).toLocaleString('zh-CN',{minimumFractionDigits:2,maximumFractionDigits:2})}},template:'<el-table-column :label="label" min-width="120" align="right"><template slot-scope="{row}">{{f(row[prop])}}</template></el-table-column>'}},data:()=>({loading:false,saving:false,invoice:{},rows:[],total:0,page:1,perPage:10,summary:{},sourceType:'purchase_settlement_source',businessDateRange:[],filters:{settlement_source_no:'',purchase_order_no:''},selected:{}}),computed:{id(){return Number(this.$route.params.id)},selectedCount(){return Object.keys(this.selected).length},matchableRows(){return this.rows.filter(row=>Number(row.available_amount)>0)},allPageSourcesSelected(){return this.matchableRows.length>0&&this.matchableRows.every(row=>Boolean(this.selected[row.id]))},selectedTotal(){return Object.values(this.selected).reduce((sum,x)=>sum+Number(x.allocated_amount||0),0)},currentMatched(){return Number(this.invoice.matched_amount||0)},unmatchedAmount(){return Math.max(0,Number(this.invoice.amount_incl_tax||0)-this.currentMatched)},isFullyMatched(){return this.unmatchedAmount<0.0001},remainingAfterSelection(){return this.unmatchedAmount-this.selectedTotal},matchComplete(){return Math.abs(this.remainingAfterSelection)<0.0001&&this.selectedTotal>0}},created(){this.init()},methods:{
async init(){this.loading=true;try{const r=await getFinanceInvoice(this.id);this.invoice=r.data.data||{};if(this.invoice.status!=='draft')this.$message.warning('已确认发票不可调整匹配');await this.load()}catch(e){this.$message.error(e.userMessage||'发票匹配加载失败')}finally{this.loading=false}},params(){return {...this.filters,business_date_start:this.businessDateRange?.[0]||'',business_date_end:this.businessDateRange?.[1]||'',page:this.page,per_page:this.perPage}},async load(){this.loading=true;try{const r=await listInvoiceMatchingSources(this.id,this.params());this.rows=r.data.data||[];this.total=Number(r.data.total||0);this.summary=r.data.summary||{}}catch(e){this.$message.error(e.userMessage||'可匹配结算来源加载失败')}finally{this.loading=false}},search(){this.page=1;this.load()},reset(){this.filters={settlement_source_no:'',purchase_order_no:''};this.businessDateRange=[];this.search()},toggleSelection(row,checked){if(checked){this.$set(this.selected,row.id,{source_business_type:'purchase_settlement_source',source_document_id:row.id,allocated_amount:String(row.available_amount||'')})}else this.$delete(this.selected,row.id)},togglePageSelection(checked){this.matchableRows.forEach(row=>this.toggleSelection(row,checked))},validateRow(row){const item=this.selected[row.id];if(!item)return;const amount=Number(item.allocated_amount||0);if(!Number.isFinite(amount)||amount<=0){item.allocated_amount='';return}if(amount>Number(row.available_amount)){item.allocated_amount=String(row.available_amount);this.$message.warning(`本次匹配金额不能超过 ${this.money(row.available_amount)} CNY`)}},money(v){return Number(v||0).toLocaleString('zh-CN',{minimumFractionDigits:2,maximumFractionDigits:2})},payload(){return Object.values(this.selected).filter(x=>Number(x.allocated_amount)>0)},async saveMatches(showMessage=true){if(this.invoice.status!=='draft'){this.$message.error('仅草稿发票允许保存匹配');return false}const items=this.payload();if(!items.length){this.$message.error('请先勾选可匹配结算来源，并填写大于 0 的本次匹配金额；未匹配金额为只读结果。');return false}if(this.remainingAfterSelection<-0.0001){this.$message.error('本次匹配金额不能超过发票未匹配金额');return false}this.saving=true;try{await saveFinanceInvoiceMatches(this.id,items);const r=await getFinanceInvoice(this.id);this.invoice=r.data.data||{};this.selected={};if(showMessage)this.$message.success('匹配已保存');await this.load();return true}catch(e){this.$message.error(e.userMessage||'保存匹配失败');return false}finally{this.saving=false}},async confirmMatches(){const persistedComplete=Math.abs(Number(this.invoice.amount_incl_tax||0)-Number(this.invoice.matched_amount||0))<0.0001&&Number(this.invoice.amount_incl_tax||0)>0;if(!this.matchComplete&&!persistedComplete)return this.$message.error('请将发票未匹配金额完整匹配后再确认');if(!persistedComplete){const saved=await this.saveMatches(false);if(!saved)return}this.saving=true;try{await confirmFinanceInvoice(this.id);this.$message.success('发票匹配已确认');this.$router.push('/finance/invoices')}catch(e){this.$message.error(e.userMessage||'确认匹配失败')}finally{this.saving=false}}
}}
</script>

<style scoped>
.invoice-match-page{min-height:calc(100vh - 64px);padding:22px 20px 30px;background:#fff;color:#17233b;box-sizing:border-box}.match-heading{display:flex;justify-content:space-between;align-items:center;margin-bottom:17px}.match-heading>div:first-child{display:flex;align-items:center;gap:28px}.match-heading h1{font-size:29px;margin:0}.match-heading span{color:#7d899c;font-size:14px}.heading-actions{display:flex;gap:14px}.green-button{background:#008b4b;border-color:#008b4b}.business-alert{border:1px solid #9fc8ff;background:#f2f8ff;margin-bottom:17px}.invoice-summary,.source-card,.match-foot{border:1px solid #e0e7ef;border-radius:5px;background:#fff}.invoice-summary{padding:17px 16px;margin-bottom:16px}.invoice-summary h2,.source-card h2{font-size:16px;margin:0 0 15px}.invoice-summary>div{display:grid;grid-template-columns:1.15fr 1.15fr 1.35fr .8fr 1.1fr 1.1fr 1.1fr;gap:12px}.invoice-summary span{font-size:13px;color:#657189}.invoice-summary b,.invoice-summary strong{display:block;margin-top:9px;color:#1b2638;font-size:15px}.invoice-summary strong{font-size:22px}.invoice-summary i{font-style:normal}.invoice-summary .green,.green{color:#009b50}.invoice-summary .red,.red{color:#ef2e2e}.source-card{padding:18px 16px}.source-filters{display:grid;grid-template-columns:1fr 1.45fr 1.75fr 1.25fr 1.25fr auto;gap:16px;align-items:end}.source-filters .el-form-item{margin-bottom:17px}.source-filters ::v-deep .el-form-item__label{line-height:20px;padding-bottom:8px;color:#26334a}.source-filters .el-select,.source-filters .el-input,.source-filters .el-date-editor{width:100%}.source-filters .el-date-editor{min-width:220px}.filter-actions{display:flex;gap:12px;margin-bottom:17px}.source-table ::v-deep .cell{white-space:normal;overflow:visible;text-overflow:clip;line-height:20px}.source-total{height:49px;border:1px solid #e4eaf0;border-top:0;display:grid;grid-template-columns:minmax(0,1fr) 120px 120px 120px 150px;align-items:center;text-align:right;padding:0 14px;box-sizing:border-box}.source-total b{text-align:left}.source-total strong{font-size:15px}.source-card>.el-pagination{text-align:right;padding:15px 2px 0}.match-foot{display:grid;grid-template-columns:1.8fr 1fr 1.2fr 1.25fr;margin-top:16px;min-height:68px}.match-foot>div{padding:14px 18px;border-right:1px solid #e9eef3}.match-foot>div:last-child{border:0}.match-foot span,.match-foot small{display:block;color:#748096;font-size:13px}.match-foot b{display:block;margin-top:8px;font-size:17px}.match-check{display:flex;align-items:center;gap:12px}.match-check>i{font-size:29px}.match-check .pass{color:#00a854}.match-check .wait{color:#fa8c16}.match-check b{margin:0 0 4px;font-size:15px}@media(max-width:1450px){.source-filters{grid-template-columns:repeat(3,minmax(0,1fr))}.filter-actions{margin-top:-2px}.invoice-summary>div{grid-template-columns:repeat(4,1fr)}}@media(max-width:800px){.invoice-match-page{padding:16px 12px}.match-heading{align-items:flex-start;flex-direction:column;gap:12px}.match-heading>div:first-child{display:block}.match-heading span{display:block;margin-top:7px}.heading-actions{flex-wrap:wrap}.invoice-summary>div,.source-filters,.match-foot{grid-template-columns:1fr}.source-filters .el-date-editor{min-width:0}.source-total{min-width:690px}.source-card{overflow:auto}.match-foot>div{border-right:0;border-bottom:1px solid #e9eef3}}
.invoice-match-page{min-height:calc(100vh - 58px);padding-right:16px;padding-left:16px}.invoice-match-page .match-heading{margin-bottom:20px}
.match-history{margin-top:16px;padding:18px 16px;border:1px solid #e0e7ef;border-radius:5px;background:#fff}.match-history h2{margin:0 0 15px;font-size:16px}.match-history ::v-deep .cell{white-space:normal;overflow:visible;text-overflow:clip}
</style>
